    import heapq

    def neighbors(r, c):
        for dr, dc in ((0, 1), (1, 0), (0, -1), (-1, 0)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid):
                yield nr, nc

    N = len(grid)
    pq = []

    # Push all starting positions with their respective values onto the heap
    for r, c in product(range(N), range(N)):
        heapq.heappush(pq, (grid[r][c], r, c, 1, [grid[r][c]]))

    # Perform a BFS using a priority queue to ensure lexicographically smallest paths
    while pq:
        current_value, r, c, length, path = heapq.heappop(pq)
        if length == k:
            return path

        for nr, nc in neighbors(r, c):
            new_path = path + [grid[nr][nc]]
            heapq.heappush(pq, (current_value + grid[nr][nc], nr, nc, length + 1, new_path))
